import { MOCK_SLACK_SENDS } from './mock'
import type {
  QuotaExhaustedPayload,
  ScoutFailurePayload,
  SlackSendResult,
} from './types'

/**
 * Force mock mode when `process.env.SLACK_LIVE !== 'true'`. Mirrors the
 * Apollo and Anthropic clients — mock-by-default keeps CI from posting
 * spurious messages to real Slack workspaces during test runs.
 */
function isMockByDefault(): boolean {
  return process.env.SLACK_LIVE !== 'true'
}

/**
 * Slack Incoming Webhook client. Constructor takes a single webhook URL —
 * Sprint 5b stores one per org (orgs.slack_webhook_url, generated by the
 * founder in their workspace's "Incoming Webhooks" app settings).
 *
 * Sprint 9 (BACKLOG-035) replaces this with the full OAuth flow + Block Kit
 * messages + interactive buttons.
 */
export class SlackWebhookClient {
  private readonly webhookUrl: string
  private readonly mockMode: boolean

  constructor(webhookUrl: string, mockMode?: boolean) {
    this.webhookUrl = webhookUrl
    this.mockMode = mockMode ?? isMockByDefault()

    if (this.mockMode && process.env.NODE_ENV !== 'test') {
      console.log('[slack] MOCK MODE ACTIVE — set SLACK_LIVE=true to post real messages')
    }
  }

  async sendText(message: string): Promise<SlackSendResult> {
    if (this.mockMode) {
      MOCK_SLACK_SENDS.push({
        webhookUrl: this.webhookUrl,
        text: message,
        sentAt: new Date(),
      })
      return { success: true, mockedPayload: { text: message } }
    }
    return this.postLive(message)
  }

  async sendScoutFailure(payload: ScoutFailurePayload): Promise<SlackSendResult> {
    const text = [
      `:rotating_light: *Scout failure* — ICP \`${payload.icpName}\``,
      `Category: \`${payload.error.category}\`${payload.error.code ? ` (${payload.error.code})` : ''}`,
      `Message: ${payload.error.message}`,
      `Run ID: \`${payload.runId}\``,
    ].join('\n')
    return this.sendText(text)
  }

  async sendQuotaExhausted(payload: QuotaExhaustedPayload): Promise<SlackSendResult> {
    const creditsLine =
      payload.creditsRemaining >= 0
        ? `Credits remaining: ${payload.creditsRemaining}`
        : 'Credits exhausted'
    const text = [
      `:warning: *${payload.provider.toUpperCase()} quota exhausted*`,
      creditsLine,
      payload.upgradeHint ?? 'Upgrade your plan to resume scouting.',
    ].join('\n')
    return this.sendText(text)
  }

  // ─── Live implementation ────────────────────────────────────────────

  private async postLive(message: string): Promise<SlackSendResult> {
    try {
      const res = await fetch(this.webhookUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ text: message }),
      })
      return { success: res.ok }
    } catch {
      // Slack webhook failures are non-blocking — the run continues, just
      // without notification. Return success=false so callers can log.
      return { success: false }
    }
  }
}
